263	func parseClaudeDistillOutput(raw string) (string, distillProviderUsage, error) {
264		usage := distillProviderUsage{Source: distillUsageSourceClaude}
265		var result struct {
266			Type          string           `json:"type"`
267			Subtype       string           `json:"subtype"`
268			IsError       bool             `json:"is_error"`
269			Result        *string          `json:"result"`
270			Usage         distillUsageJSON `json:"usage"`
271			DurationMS    int64            `json:"duration_ms"`
272			DurationAPIMS int64            `json:"duration_api_ms"`
273		}
274		if err := json.Unmarshal([]byte(strings.TrimSpace(raw)), &result); err != nil {
275			return "", usage, fmt.Errorf("parse claude JSON: %w", err)
276		}
277		usage.DurationMS = result.DurationMS
278		usage.DurationAPIMS = result.DurationAPIMS
279		if err := result.Usage.validate(); err != nil {
280			return "", usage, fmt.Errorf("claude usage: %w", err)
281		}
282		result.Usage.addTo(&usage)
283		if result.IsError {
284			message := ""
285			if result.Result != nil {
286				message = strings.TrimSpace(*result.Result)
287			}
288			if message == "" {
289				message = result.Subtype
290			}
291			return "", usage, fmt.Errorf("claude returned an error: %s", message)
292		}
293		if result.Result == nil {
294			return "", usage, fmt.Errorf("claude JSON contained no result")
295		}
296		return *result.Result, usage, nil
297	}
